<div class="page-heading"><div><h1>Punto de venta</h1><p>El sistema seleccionará automáticamente los lotes mediante FEFO</p></div></div><div class="row g-4" id="posApp"><div class="col-xl-7"><div class="panel"><div class="input-group mb-3"><span class="input-group-text"><i class="bi bi-search"></i></span><input class="form-control" id="productSearch" placeholder="Buscar por nombre o código" autocomplete="off"></div><div class="product-grid" id="productGrid"><?php foreach($productos as$p):?><button type="button" class="product-card" data-product='<?=e(json_encode(['id'=>(int)$p['id'],'codigo'=>$p['codigo'],'nombre'=>$p['nombre'],'detalle'=>trim(($p['concentracion']??'').' '.($p['presentacion']??'')),'precio'=>(float)$p['precio_venta'],'stock'=>(int)$p['stock']],JSON_UNESCAPED_UNICODE))?>'><div class="product-header"><div class="product-visual"><?php if(!empty($p['imagen'])):?><img src="<?=url('public/uploads/'.e($p['imagen']))?>" alt="<?=e($p['nombre'])?>" class="product-img"><?php else:?><span class="product-placeholder"><i class="bi bi-capsule"></i></span><?php endif?></div><div class="product-meta"><span class="product-name"><?=e($p['nombre'])?></span><small><?=e($p['codigo'].' · '.trim(($p['concentracion']??'').' '.($p['presentacion']??'')))?></small></div></div><span><strong><?=money($p['precio_venta'])?></strong><em>Stock <?=$p['stock']?></em></span></button><?php endforeach?></div></div></div><div class="col-xl-5"><form class="panel pos-cart" id="posForm" method="post" action="<?=url('index.php?page=venta-save')?>" data-stock-url="<?=url('index.php?page=stock-check')?>"><?=csrf_field()?><input type="hidden" name="items" id="itemsInput"><h2 class="h5">Detalle de venta</h2><div id="stockMessage" class="d-none" role="alert"></div><div id="cartItems" class="cart-items"><div class="empty-state">Selecciona productos para comenzar</div></div><div class="cart-total"><span>Total</span><strong id="cartTotal">S/ 0.00</strong></div><div class="row g-2 mt-2"><div class="col-12"><input class="form-control" name="cliente_nombre" maxlength="120" placeholder="Cliente (opcional)"></div><div class="col-6"><input class="form-control" name="cliente_documento" maxlength="20" placeholder="Documento"></div><div class="col-6"><select class="form-select" name="metodo_pago"><option value="efectivo">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="tarjeta">Tarjeta</option></select></div></div><button class="btn btn-primary btn-lg w-100 mt-3" id="saleSubmit" disabled>Verificar y confirmar venta</button></form></div></div>
